import{_ as t,o as r,c as e,a3 as l}from"./chunks/framework.Dj4Lt7vj.js";const g=JSON.parse('{"title":"情景与触发规则","description":"","frontmatter":{"title":"情景与触发规则"},"headers":[],"relativePath":"solution/triggers.md","filePath":"solution/triggers.md","lastUpdated":1787949005000}'),o={name:"solution/triggers.md"};function i(s,a,n,c,d,h){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="情景与触发规则" tabindex="-1">情景与触发规则 <a class="header-anchor" href="#情景与触发规则" aria-label="Permalink to &quot;情景与触发规则&quot;">​</a></h1><p>一套话术打天下会顾此失彼：售前要热情推销，售后要安抚解决。「情景配置」允许你在一个方案里为不同客户情景配置专用的回复设定和触发规则。</p><p>入口：方案编辑器 → 「AI 设置」→ 右上角「情景配置」。</p><div class="warning custom-block"><p class="custom-block-title">按套餐开放</p><p>自定义触发规则和多情景分流按套餐开放。当前套餐未包含时请联系销售开通，具体以「账单」页为准，见<a href="/aicare-docs/start/plan">套餐与开通</a>。</p></div><h2 id="默认设置和情景" tabindex="-1">默认设置和情景 <a class="header-anchor" href="#默认设置和情景" aria-label="Permalink to &quot;默认设置和情景&quot;">​</a></h2><ul><li>每个方案有且仅有一个<strong>默认设置</strong>：没有命中任何触发规则的消息由它处理。默认设置不能配置触发规则。</li><li><strong>情景</strong>是额外的回复设定：售后情景、议价情景、大促咨询情景……每个情景有自己的角色设定和话术要求。</li><li>情景可以单独<strong>停用</strong>：停用后即使触发规则命中也会跳过，回到默认设置处理。</li></ul><h2 id="触发规则" tabindex="-1">触发规则 <a class="header-anchor" href="#触发规则" aria-label="Permalink to &quot;触发规则&quot;">​</a></h2><p>触发规则决定什么时候切换到某个情景。每个情景可以加多条触发条件，支持两种：</p><ul><li><strong>关键词</strong>：消息里出现指定词时命中。比如「退款、退货、坏了」触发售后情景。</li><li><strong>意图描述</strong>：用一句话描述这类客户想干什么，AI 语义判断是否命中。比如「顾客对价格不满意，想要优惠」。</li></ul><p>关键词准确但死板，意图描述灵活但依赖 AI 判断。拿不准就两种都配。</p><h2 id="配置步骤" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤" aria-label="Permalink to &quot;配置步骤&quot;">​</a></h2><ol><li>在情景配置页新建情景，写好名字和这个情景专用的回复设定。</li><li>打开该情景的「触发规则」标签页，添加触发条件。</li><li>启用情景。</li><li>用<a href="/aicare-docs/solution/test">对话测试</a>验证：发几条应该命中的消息，确认路由说明里显示进入了正确的情景。</li></ol><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ul><li><strong>从少开始</strong>。先只拆一个售后情景，跑顺了再细分。情景太多、触发规则互相重叠，反而难排查。</li><li><strong>触发规则要互斥</strong>。两个情景都配了「退款」这个词，命中哪个不直观。规则尽量不重叠。</li><li><strong>在聊天记录里核对</strong>。<a href="/aicare-docs/workspace/records#会话详情">会话详情</a>的路由说明会写明这条消息由哪个情景处理、怎么命中的，是排查分流问题的第一手资料。</li></ul>',14)])])}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
